def test_hyb_mgga_xc_b88b95_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_b88b95", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.169343327906038e+00, -3.110093393985409e+00, -3.027116107823883e+00, -2.912268288688890e+00, -2.755974318168109e+00, -2.548374678217630e+00, -2.282017413173617e+00, -1.956635516049397e+00, -1.585276375514033e+00, -1.196291107488211e+00, -8.177694016398438e-01, -5.663445240663553e-01, -4.724244340386292e-01, -3.869129999376811e-01, -2.825238626142604e-01, -1.833222906598600e-01, -1.124627612314907e-01, -6.912920039992856e-02, -4.393102668717138e-02, -3.003851073267873e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


